const out = [];
const store = $getWorkflowStaticData('global');
store.knownKeys = store.knownKeys || {};
store.knownProducts = store.knownProducts || {};
const today = new Date().toISOString().slice(0,10);
const toSerial = (s) => { if(!s) return ''; const m=String(s).match(/(\d+)\/(\d+)\/(\d+)/); if(!m) return s; const d=Date.UTC(+m[3],+m[1]-1,+m[2]); return Math.floor((d-Date.UTC(1899,11,30))/86400000); };
const short = (p) => { if(!p) return p; let s = p.split(',')[0].trim(); return s.length>50 ? s.slice(0,50).trim()+'…' : s; };
const mkLink = (u) => { if(!u) return ''; let s = String(u).replace(/"/g,''); if (s.length > 250) s = s.slice(0,250); return '=HYPERLINK("' + s + '","Link")'; };
const extractSpec = (name) => { if(!name) return {v:'',s:''}; const re=/(\d+(?:\.\d+)?)\s*(kg|mg|µg|g|ml|µl|ul|l|mm|cm|m|oz|inch|in)\b/gi; const ms=[...String(name).matchAll(re)]; return ms.length===1 ? {v:ms[0][1], s:ms[0][2]} : {v:'',s:''}; };
const kw = (p) => encodeURIComponent(String(p||'').split(/\s+/).slice(0,8).join(' ').slice(0,80));
function orderBlocks(t){ const re=/Order #\s*\n\s*(\d{3}-\d{7}-\d{7})/g; const marks=[]; let m; while((m=re.exec(t))!==null) marks.push({ord:m[1], idx:m.index}); if(!marks.length) return null; const blocks=[]; for(let i=0;i<marks.length;i++){ const seg=t.slice(marks[i].idx, i+1<marks.length?marks[i+1].idx:t.length); blocks.push({ord:marks[i].ord, seg}); } return blocks; }
for (const item of $input.all()) {
  const m = item.json;
  const text = m.text || m.textPlain || m.snippet || '';
  const html = m.html || '';
  const full = text + '\n' + html;
  const subject = m.subject || (m.headers && m.headers.subject) || '';
  const subjClean = subject.replace(/^fwd:\s*/i,'');
  const fromRaw = (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || '';
  const dateRaw = m.date || m.internalDate || null;
  let dateStr = '';
  if (dateRaw) { const d=new Date(isNaN(dateRaw)?dateRaw:Number(dateRaw)); if(!isNaN(d)) dateStr=(d.getUTCMonth()+1)+'/'+d.getUTCDate()+'/'+d.getUTCFullYear(); }
  const subjLc = subject.toLowerCase();
  const isConf = /auto-confirm@amazon/i.test(fromRaw) || /^ordered:/i.test(subjClean);
  let status='', emailType='update';
  if (isConf) { status='Ordered'; emailType='confirmation'; }
  else if (/^dispatched/i.test(subjClean)) status='Dispatched';
  else if (/out for delivery/i.test(subjLc)) status='Out for delivery';
  else if (/^delivered/i.test(subjClean)) status='Delivered';
  else if (/cancel/i.test(subjLc)) status='Cancelled';
  else if (/your return of/i.test(subjLc)) status='Returned';
  else if (/your refund for/i.test(subjLc)) status='Refunded';
  else continue;
  const who = ''; // Add a generic buyer parser if this field is needed.
  if (emailType === 'confirmation') {
    let blocks = orderBlocks(text);
    if (!blocks) { const one = ((text.match(/Order #\s*\n?\s*(\d{3}-\d{7}-\d{7})/)||[])[1]) || ((full.match(/\d{3}-\d{7}-\d{7}/)||[])[0]) || ''; blocks=[{ord:one, seg:text}]; }
    for (const blk of blocks) {
      const orderNo = blk.ord, seg = blk.seg;
      const grab = (re) => { const x = seg.match(re); return x ? x[1].trim() : ''; };
      const total = grab(/Total\s*\n\s*([\d.,]+)\s*GBP/);
      const arriving = grab(/(Arriving[^\n]+|Now expected[^\n]+)/);
      const veo = grab(/(https:\/\/www\.amazon\.co\.uk\/your-orders\/order-details[^\s]+)/);
      const trk = grab(/(https:\/\/www\.amazon\.co\.uk\/progress-tracker[^\s]+)/);
      const orderLink = veo || trk || '';
      const amzItem = (p) => p ? ('https://www.amazon.co.uk/s?k=' + kw(p)) : orderLink;
      const liRe = /\*\s*(.+?)\n\s*Quantity:\s*(\d+)(?:\s*\n\s*([\d.,]+)\s*GBP)?/g;
      let li, found=false;
      while ((li = liRe.exec(seg)) !== null) { found=true;
        const name = li[1].trim(); const sp = short(name); const u = amzItem(name);
        if (orderNo) { store.knownKeys[orderNo]=true; store.knownKeys[orderNo+'|'+sp]=true; }
        store.knownProducts[sp]=true;
        out.push({ json: { emailType, Date: toSerial(dateStr), Who: who, product: sp, volume: extractSpec(name).v, State: extractSpec(name).s, Items: Number(li[2]), 'Price (Inclu. VAT)': (li[3]||total)? Number(String(li[3]||total).replace(/,/g,'')):'', Supplier:'Amazon', URL: u, Status: status, 'Estimated delivery date': arriving||'', OrderNo: orderNo, LineKey: orderNo+'|'+sp } });
      }
      if (!found && orderNo) { store.knownKeys[orderNo]=true; out.push({ json: { emailType, Date: toSerial(dateStr), Who: who, product:'', Supplier:'Amazon', URL: orderLink, Status: status, 'Estimated delivery date': arriving||'', OrderNo: orderNo, LineKey:'' } }); }
    }
  } else {
    const items = [...text.matchAll(/\*\s*(.+?)\n\s*Quantity:\s*(\d+)/g)];
    const allOrders = [...new Set(text.match(/\d{3}-\d{7}-\d{7}/g) || [])];
    if (items.length) {
      for (const it of items) {
        const sp = short(it[1].trim());
        out.push({ json: { emailType:'update', matchBy:'line', Status: status, product: sp, orderNos: allOrders, Supplier:'Amazon' } });
      }
    } else {
      let any=false;
      for (const ord of allOrders) { if (store.knownKeys[ord]) { any=true; out.push({ json: { emailType:'update', matchBy:'order', Status: status, OrderNo: ord } }); } }
      if (!any) out.push({ json: { emailType:'needsReview', When: today, Reason:'Amazon status update (no items listed) for an unknown order', Supplier:'Amazon', Product:'', OrderNo: allOrders.join(', '), Status: status, Subject: subject } });
    }
  }
}
return out;

const out = [];
const toSerial = (s) => { if(!s) return ''; const m=String(s).match(/(\d{4})-(\d{2})-(\d{2})/); if(!m) return s; const d=Date.UTC(+m[1],+m[2]-1,+m[3]); return Math.floor((d-Date.UTC(1899,11,30))/86400000); };
const normRef = (s) => String(s || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const short = (p) => { if(!p) return ''; let s = String(p).split(/,\s+/)[0].trim(); return s.length>50 ? s.slice(0,50).trim()+'…' : s; };
const store = $getWorkflowStaticData('global');
store.supplierSites = store.supplierSites || {};
store.knownKeys = store.knownKeys || {};
store.knownProducts = store.knownProducts || {};
store.trackingMap = store.trackingMap || {};
const today = new Date().toISOString().slice(0,10);
const SUPPLIER_SITES = [];
function cleanDomain(u){ if(!u) return ''; let s=String(u).trim().toLowerCase(); s=s.replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/^mail\./,'').replace(/[\/?#].*$/,'').trim(); return /^[a-z0-9.-]+\.[a-z]{2,}$/.test(s)?s:''; }
function domainFor(supplier, learnedUrl){ const s=String(supplier||'').trim().toLowerCase(); if(!s) return ''; for (const [k,dom] of SUPPLIER_SITES) if (s.includes(k)) return dom; if (store.supplierSites[s]) return store.supplierSites[s]; const dom=cleanDomain(learnedUrl); if (dom){ store.supplierSites[s]=dom; return dom; } return ''; }
function itemLink(supplier, product, learnedUrl){ const p=String(product||'').split(/\s+/).slice(0,8).join(' ').slice(0,80).trim(); const dom=domainFor(supplier, learnedUrl); if (dom && p) return 'https://www.google.com/search?q='+encodeURIComponent('site:'+dom+' '+p); if (dom) return 'https://'+dom; const q=(String(supplier||'')+' '+p).trim(); return q?'https://www.google.com/search?q='+encodeURIComponent(q):''; }
function priceOf(it, cur){ const a=(it.gross!==undefined&&it.gross!=='')?it.gross:(it.net!==undefined&&it.net!==''?it.net:it.unit_price); if(a===''||a===null||a===undefined) return ''; return (cur&&cur!=='GBP')?(cur+' '+a):a; }
function realProduct(p){ const s = short(p || ''); return (s && !/^[\d\W]+$/.test(s)) ? s : ''; }
for (const item of $input.all()) {
  const parts = (item.json && item.json.content) || [];
  const textPart = parts.find(p => p.type === 'text') || parts[0] || {};
  let raw = (textPart.text || '').replace(/```json|```/gi, '').trim();
  let d = {};
  try { d = JSON.parse(raw); } catch (e) { continue; }
  const ref = normRef(d.order_ref || d.invoice_no || '');
  if (d.tracking) { const tk = normRef(d.tracking); if (tk && ref) store.trackingMap[tk] = ref; }
  const who = String(d.buyer || '').split('/')[0].trim();
  const cur = String(d.currency || '').toUpperCase();
  const supplier = d.supplier || '';
  const dt = String(d.docType || '').toLowerCase();
  const isNew = ['order','invoice','confirmation','acknowledgement'].includes(dt);
  const st = String(d.status || '').trim();
  let items = Array.isArray(d.items) ? d.items : [];
  if (!items.length && (d.product)) items = [{ product:d.product, sku:d.sku, volume:d.volume, unit:d.unit, quantity:d.quantity, unit_price:d.unit_price, net:d.net, gross:d.gross }];
  if (isNew) {
    const goodItems = items.filter(it => realProduct(it.product));
    if (!goodItems.length) continue;
    for (const it of goodItems) {
      const prod = realProduct(it.product);
      const sku = String(it.sku || '').trim();
      const skuN = sku.replace(/[^A-Za-z0-9]/g,'').toUpperCase();
      const keyPart = skuN || prod;
      const productLink = (d.link && /^https?:/i.test(d.link) && !/wp-admin/i.test(d.link)) ? d.link : '';
      const url = productLink || itemLink(supplier, prod, d.supplier_url);
      if (ref) { store.knownKeys[ref]=true; store.knownKeys[ref+'|'+keyPart]=true; }
      store.knownProducts[prod]=true;
      out.push({ json: {
        emailType:'confirmation', Date: toSerial(d.invoice_date || d.order_date || ''), Who: who,
        product: prod, SKU: sku, volume: it.volume || '', State: it.unit || '', Items: it.quantity || '',
        'Price (Inclu. VAT)': priceOf(it, cur), Supplier: supplier, URL: url,
        Status: st || 'Ordered', 'Estimated delivery date': '',
        'Invoice sent to accountant': (dt==='invoice') ? 'Yes' : '',
        OrderNo: ref, LineKey: ref + '|' + keyPart }});
    }
  } else {
    if (!/^(dispatched|out for delivery|delivered|cancelled|returned|refunded)$/i.test(st)) continue;
    const named = items.filter(it => realProduct(it.product) || String(it.sku||'').trim());
    if (named.length) {
      for (const it of named) {
        const prod = realProduct(it.product);
        const sku = String(it.sku || '').trim();
        out.push({ json:{ emailType:'update', matchBy:'line', Status: st, product: prod, sku: sku, orderNos: ref ? [ref] : [], Supplier: supplier } });
      }
    } else if (ref) {
      if (store.knownKeys[ref]) out.push({ json:{ emailType:'update', matchBy:'order', Status: st, OrderNo: ref } });
      else out.push({ json:{ emailType:'needsReview', When: today, Reason:'Supplier status update for an order not in the sheet', Supplier: supplier, Product:'', OrderNo: ref, Status: st, Subject: ($json.subject || '') } });
    }
  }
}
return out;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary || {};
  const key = Object.keys(bin).find(k => String(bin[k].mimeType || '').includes('pdf'));
  if (!key) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  const b64 = buf.toString('base64');
  const instructions = 'You log procurement emails into a spreadsheet. Output RAW JSON only, no code fences, no prose. Schema: {"docType":"order|invoice|dispatch|delivery|other","supplier":"","buyer":"","order_ref":"the order or PO reference exactly as shown, keep punctuation","invoice_no":"","invoice_date":"YYYY-MM-DD","currency":"","status":"Ordered|Dispatched|Out for delivery|Delivered|Cancelled|Returned|Refunded or empty","supplier_url":"supplier website if shown else empty","tracking":"","carrier":"","items":[{"product":"short recognisable product name","sku":"supplier catalogue/product/item number for this line, empty if none","volume":"","unit":"","quantity":"","unit_price":"","net":"","gross":""}]}. List every distinct PRODUCT as its own item. Do NOT include shipping, carriage, fuel surcharge, minimum order charge, handling or VAT lines as items. Use empty string for anything not shown.';
  const body = { model: 'claude-sonnet-5', max_tokens: 2000, messages: [ { role: 'user', content: [ { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }, { type: 'text', text: instructions } ] } ] };
  out.push({ json: { claudeBody: JSON.stringify(body) } });
}
return out;

const store = $getWorkflowStaticData('global');
store.sentInvoices = store.sentInvoices || {};
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const json = items[i].json || {};
  const bin = items[i].binary || {};
  const fromRaw = (json.from && (json.from.text || (json.from.value && json.from.value[0] && json.from.value[0].address))) || '';
  if (/operations@example\.com/i.test(fromRaw)) continue;            // never re-forward our own sends (loop guard)
  const msgId = json.id || json.messageId || '';
  if (msgId && store.sentInvoices[msgId]) continue;                       // already forwarded this email
  const pdfKeys = Object.keys(bin).filter(k => String(bin[k].mimeType || '').includes('pdf'));
  const picked = pdfKeys.filter(k => /invoice|receipt|vat/i.test(bin[k].fileName || '')); // STRICT: filename must say invoice/receipt/vat
  if (!picked.length) continue;
  const supplier = (fromRaw.split('<')[0].trim()) || 'supplier';
  for (const key of picked) {
    out.push({ json: { to: 'accountant-inbox@example.com', subject: 'Invoice – ' + supplier, file: bin[key].fileName || 'invoice.pdf' }, binary: { data: bin[key] } });
  }
  if (msgId) store.sentInvoices[msgId] = true;
}
return out;

const rows = $('Read log').all().map(i => i.json || {});
const norm = s => String(s || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const TERMINAL = /^(delivered|cancelled|returned|refunded)$/i;
const NEGATIVE = /^(cancelled|returned|refunded)$/i;
const ORDER = ['ordered','dispatched','out for delivery','delivered'];
const rank = s => { const i = ORDER.indexOf(String(s||'').toLowerCase().trim()); return i < 0 ? 0 : i; };
const today = new Date().toISOString().slice(0,10);
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const prod = String(j.product || '').trim();
  const usku = norm(j.sku);
  const st = String(j.Status || '').trim();
  const orderNos = (Array.isArray(j.orderNos) ? j.orderNos : []).map(norm).filter(Boolean);
  let cands = [];
  if (usku) cands = rows.filter(r => norm(r.SKU) === usku);
  if (!cands.length && prod) cands = rows.filter(r => String(r.product || '').trim() === prod);
  if (orderNos.length) {
    const byOrder = cands.filter(r => orderNos.includes(norm(r.OrderNo)));
    if (byOrder.length) {
      cands = byOrder;
    } else if (NEGATIVE.test(st)) {
      out.push({ json: { emailType:'needsReview', When: today, Reason:'Cancel/return/refund for an order not in the sheet (item exists under a different order)', Supplier: j.Supplier || '', Product: prod || j.sku || '', OrderNo: (j.orderNos||[]).join(', '), Status: st, Subject: j.Subject || '' } });
      continue;
    }
  }
  const open = cands.filter(r => !TERMINAL.test(String(r.Status || '')));
  let pick = null;
  if (open.length) pick = open.find(r => rank(r.Status) < rank(st)) || open[0];
  else if (cands.length) pick = cands[cands.length - 1];
  if (pick && pick.LineKey) {
    out.push({ json: { emailType:'update', matchBy:'line', LineKey: pick.LineKey, Status: st } });
  } else {
    out.push({ json: { emailType:'needsReview', When: today, Reason: cands.length ? 'All matching rows already closed - status not applied' : 'No matching product/SKU row found', Supplier: j.Supplier || '', Product: prod || j.sku || '', OrderNo: (j.orderNos||[]).join(', '), Status: st, Subject: j.Subject || '' } });
  }
}
return out;

const out = [];
const store = $getWorkflowStaticData('global');
store.trackingMap = store.trackingMap || {};
const today = new Date().toISOString().slice(0,10);
const normTrk = s => String(s || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
for (const item of $input.all()) {
  const m = item.json;
  const subject = m.subject || (m.headers && m.headers.subject) || '';
  const subjLc = subject.toLowerCase();
  const fromRaw = (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || '';
  const text = m.text || '';
  let html = String(m.html || '');
  html = html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&#x27;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ');
  const body = (text && text.trim()) ? text : html;
  const carrier = /royalmail/i.test(fromRaw) ? 'Royal Mail' : /dpd/i.test(fromRaw) ? 'DPD' : /dhl/i.test(fromRaw) ? 'DHL' : /fedex/i.test(fromRaw) ? 'FedEx' : /ups\.com/i.test(fromRaw) ? 'UPS' : /parcelforce/i.test(fromRaw) ? 'Parcelforce' : (/evri|hermes/i.test(fromRaw) ? 'Evri' : 'Courier');
  let trk = '';
  const mrm = body.match(/\b([A-Z]{2}\d{9}GB)\b/);
  const mdpd = body.match(/\b(\d{4}\s?\d{4}\s?\d{3}\s?\d{3})\b/);
  if (mrm) trk = mrm[1];
  else if (mdpd) trk = mdpd[1];
  else { const mg = body.match(/\b([A-Z0-9]{10,22})\b/); if (mg) trk = mg[1]; }
  const key = normTrk(trk);
  let status = '';
  if (/delivered/i.test(subjLc)) status = 'Delivered';
  else if (/out for delivery|delivered today|due to be delivered|will be delivered|being delivered/i.test(subjLc)) status = 'Out for delivery';
  else if (/on its way|on the way|expecting|in transit|shipped|dispatched|with its courier/i.test(subjLc)) status = 'Dispatched';
  else if (/delay/i.test(subjLc)) status = 'Delayed';
  else continue;
  const orderRef = (key && store.trackingMap[key]) ? store.trackingMap[key] : '';
  if (orderRef) {
    out.push({ json: { emailType:'update', matchBy:'order', Status: status, OrderNo: orderRef } });
  } else {
    out.push({ json: { emailType:'needsReview', When: today, Reason: key ? ('Courier ('+carrier+') update - tracking '+trk+' not linked to an order yet') : ('Courier ('+carrier+') update - no tracking number found'), Supplier: carrier, Product: '', OrderNo: '', Status: status, Subject: subject } });
  }
}
return out;

const store = $getWorkflowStaticData('global');
store.sentInvoices = store.sentInvoices || {};
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const msgId = m.id || m.messageId || (m.headers && m.headers['message-id']) || '';
  const subject = m.subject || (m.headers && m.headers.subject) || '';
  const text = m.text || '';
  const html = m.html || '';
  const bin = item.binary || {};
  const hasPdf = Object.keys(bin).some(k => String(bin[k].mimeType || '').includes('pdf'));
  if (hasPdf) continue;
  const subjLc = subject.toLowerCase();
  const isReceipt = /\breceipt\b|\binvoice\b|vat invoice|payment (received|confirmation|successful)/.test(subjLc);
  if (!isReceipt) continue;
  if (msgId && store.sentInvoices[msgId]) continue;
  const fromRaw = (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || '';
  const supplier = (fromRaw.split('<')[0].trim()) || 'supplier';
  const bodyHtml = (html && html.trim()) ? html : ('<pre>' + String(text).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c])) + '</pre>');
  out.push({ json: {
    to: 'accountant-inbox@example.com',
    cc: 'you@example.com',
    subject: 'Fwd: ' + subject,
    message: '<p>Automated receipt forward from operations@example.com (no PDF attached; receipt is in the email below).</p><hr>' + bodyHtml,
    supplier
  }});
  if (msgId) store.sentInvoices[msgId] = true;
}
return out;

const rows = $('Read log').all().map(i => i.json || {});
const seen = new Set(rows.map(r => String(r.LineKey || '').trim()).filter(Boolean));
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const lk = String(j.LineKey || '').trim();
  if (lk && seen.has(lk)) continue;
  if (lk) seen.add(lk);
  out.push({ json: j });
}
return out;
